  "p068": {"q":"解析說「柏」的兩個讀音怎麼分？","o":["都讀ㄅㄞˇ","都讀ㄅㄛˊ","柏樹讀ㄅㄞˇ、柏油讀ㄅㄛˊ","樹木義審訂音讀ㄅㄛˊ（松柏）；外來語音譯「柏油」讀ㄅㄞˇ"],"a":3},
  "p069": {"q":"依解析，「剖析」是怎麼引申來的？","o":["用刀切開（解剖）→把道理切開細看","用手撕開","否定別人","破開果實"],"a":0},
  "p070": {"q":"解析說「畸」的本義是什麼、為什麼常誤讀？","o":["本義是奇怪，誤讀成ㄐㄧ","本義是劃分田地後剩下的不方正零地；從「奇」得聲卻讀ㄐㄧ，常被誤讀成ㄑㄧˊ","本義是田地肥沃","本義是奇數"],"a":1},
  "p071": {"q":"依解析，台灣審訂音「堤防」的「堤」讀什麼？","o":["ㄉㄧ","ㄕˋ","ㄊㄧˊ（與「提」同音）","ㄉㄧˊ"],"a":2},
  "p072": {"q":"解析說「駐紮」是怎麼引申的？","o":["軍隊駐守要用槍","紮營要用木頭","士兵要打結","軍隊「捆好行囊安營」（紮＝用繩捆綁）"],"a":3},
  "p073": {"q":"依解析，「匕首」的「匕」字形像什麼？","o":["像古代取食的匙勺，也像短劍之形（柄頭如匙）","像一匹布","像人跪著","像刀鋒"],"a":0},
